function mk(o) {
  return {
    id: o.id, title: o.title, cls: o.cls, subject: o.subject, type: o.type,
    publication: o.publication, author: o.author, language: o.language || "English",
    pages: o.pages, downloads: o.downloads, rating: o.rating,
    addedAt: new Date(BASE_DATE.getTime() - (o.added || 0) * 86400000).toISOString(),
    chapters: o.chapters || [], featured: !!o.featured, popular: !!o.popular,
    desc: o.desc, cover: null, file: null,
  };
}

