const SB_SQL = `-- ============================================================
-- PikaStudy backend setup — paste into Supabase SQL Editor and Run
-- ============================================================

-- 1) TABLES
create table if not exists public.books (
  id uuid primary key,
  title text not null,
  cls int not null check (cls in (10,11,12)),
  subject text not null,
  type text not null,
  publication text not null,
  author text default '',
  language text default 'English',
  pages int default 0,
  downloads int default 0,
  rating numeric(3,1) default 0,
  description text default '',
  chapters jsonb default '[]',
  featured boolean default false,
  popular boolean default false,
  cover_url text,
  file_url text,
  added_at timestamptz default now()
);

create table if not exists public.requests (
  id uuid primary key default gen_random_uuid(),
  name text default '',
  cls int,
  subject text default '',
  title text not null,
  note text default '',
  status text default 'new',
  created_at timestamptz default now()
);

create table if not exists public.subjects (
  id uuid primary key default gen_random_uuid(),
  cls int not null,
  name text not null,
  unique (cls, name)
);

create table if not exists public.publications (
  id uuid primary key default gen_random_uuid(),
  name text not null unique
);

-- 2) ROW LEVEL SECURITY
alter table public.books enable row level security;
alter table public.requests enable row level security;
alter table public.subjects enable row level security;
alter table public.publications enable row level security;

drop policy if exists "public read books" on public.books;
create policy "public read books" on public.books for select using (true);
drop policy if exists "admins manage books" on public.books;
create policy "admins manage books" on public.books for all to authenticated using (true) with check (true);

drop policy if exists "students submit requests" on public.requests;
create policy "students submit requests" on public.requests for insert to anon with check (true);
drop policy if exists "admins manage requests" on public.requests;
create policy "admins manage requests" on public.requests for all to authenticated using (true) with check (true);

drop policy if exists "public read subjects" on public.subjects;
create policy "public read subjects" on public.subjects for select using (true);
drop policy if exists "admins manage subjects" on public.subjects;
create policy "admins manage subjects" on public.subjects for all to authenticated using (true) with check (true);

drop policy if exists "public read publications" on public.publications;
create policy "public read publications" on public.publications for select using (true);
drop policy if exists "admins manage publications" on public.publications;
create policy "admins manage publications" on public.publications for all to authenticated using (true) with check (true);

-- 3) STORAGE (covers & PDFs)
insert into storage.buckets (id, name, public) values ('pikastudy', 'pikastudy', true)
  on conflict (id) do nothing;

drop policy if exists "public read files" on storage.objects;
create policy "public read files" on storage.objects for select using (bucket_id = 'pikastudy');
drop policy if exists "admins upload files" on storage.objects;
create policy "admins upload files" on storage.objects for insert to authenticated with check (bucket_id = 'pikastudy');
drop policy if exists "admins update files" on storage.objects;
create policy "admins update files" on storage.objects for update to authenticated using (bucket_id = 'pikastudy');
drop policy if exists "admins delete files" on storage.objects;
create policy "admins delete files" on storage.objects for delete to authenticated using (bucket_id = 'pikastudy');

-- Done! Now: Authentication > Users > Add user (your admin email + password),
-- then open Admin > Connect in PikaStudy and connect.`;

